-- NEXPLAY: banco próprio Neon, versão inicial. Não execute em banco com tabelas preexistentes de outros aplicativos.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS resellers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text, status text NOT NULL DEFAULT 'ativo' CHECK(status IN ('ativo','suspenso')), activation_limit integer NOT NULL DEFAULT 100 CHECK(activation_limit>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('master','revendedor','suporte')), reseller_id uuid REFERENCES resellers(id), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK(role <> 'revendedor' OR reseller_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reseller_id uuid NOT NULL REFERENCES resellers(id), name text NOT NULL, whatsapp text NOT NULL DEFAULT '', plan text NOT NULL, tech text NOT NULL CHECK(tech IN ('IPTV','P2P')), status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','ativo','suspenso','expirado')), devices integer NOT NULL DEFAULT 1 CHECK(devices BETWEEN 1 AND 8), activated_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reseller_id uuid NOT NULL REFERENCES resellers(id), tech text NOT NULL CHECK(tech IN ('IPTV','P2P')), pack text NOT NULL, hours integer NOT NULL CHECK(hours IN (1,2,6,12,24)), contact text NOT NULL, devices integer NOT NULL CHECK(devices BETWEEN 1 AND 4), status text NOT NULL DEFAULT 'pendente_provedor' CHECK(status IN ('pendente_provedor','ativo','expirado','cancelado')), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS trials_reseller_created_idx ON trials (reseller_id,created_at DESC);
CREATE TABLE IF NOT EXISTS subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), reseller_id uuid NOT NULL REFERENCES resellers(id), plan text NOT NULL, tech text NOT NULL CHECK(tech IN ('IPTV','P2P')), price numeric(12,2) NOT NULL CHECK(price>=0), status text NOT NULL DEFAULT 'pendente_ativacao', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reseller_id uuid NOT NULL REFERENCES resellers(id), period text NOT NULL, activations integer NOT NULL DEFAULT 0, amount numeric(12,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('paga','pendente','atrasada')), due_at date, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(reseller_id,period));
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, target_type text, target_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, ip_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS login_attempts_recent_idx ON login_attempts(email,created_at DESC);
